// src/components/Dashboard/ReleaseMaster.js
import React from 'react';

/**
 * [PH1-B] Release Master View
 * For Phase 1, we provide an in-page viewer placeholder. True live in-place editing of a PPTX
 * requires Office Online (Graph/SharePoint + Office.js) which we'll wire in Phase 2.
 * For now we load the local PPTX asset and show a fallback download/open link.
 */
export default function ReleaseMaster() {
  // If you place the PPT under /public/files, you can reference it directly:
  // e.g., <iframe src="/files/PBPT RM - Master.pptx">...</iframe> — most browsers won't render PPTX natively.
  // So Phase 1 shows a helpful message + a link. Phase 2: integrate Office embed for editing.
  return (
    <div style={{ padding: 8 }}>
      <div className="muted" style={{ marginBottom: 8 }}>
        PBPT RM – Master deck preview. Editing in-page will be enabled in Phase 2 via Office Online.
      </div>
      <a href="/files/PBPT RM - Master.pptx" target="_blank" rel="noreferrer" className="go-btn">
        Open “PBPT RM - Master.pptx”
      </a>
    </div>
  );
}
